class Solution { public:int destroyTargets(vector<int>& nums,int space){unordered_map<int,int> frequency,minimum;for(int value:nums){int remainder=value%space;++frequency[remainder];if(!minimum.count(remainder))minimum[remainder]=value;else minimum[remainder]=min(minimum[remainder],value);}int best=0,answer=INT_MAX;for(auto [remainder,count]:frequency){int value=minimum[remainder];if(count>best||(count==best&&value<answer)){best=count;answer=value;}}return answer;} };
